// J-57: a form's calculations run once the user has agreed to its scripts.
// J-97 proves the other half (nothing is calculated before the answer). The
// fixture form_scripts.pdf, generated by make_form_scripts.py, has qty, price
// and a read-only total that is calculated as qty x price (AFSimple_Calculate,
// a /AA /C action). The user agrees through the real consent bar; typing in
// qty or price must then change total, the saved file must carry it, and a
// reopened file must show it before any script has run again.

import { expect } from 'vitest';
import { journey, type Journey } from './lib/journey';
import { fill, save, sleep, waitDirty } from './lib/ui';

const field = (name: string): string => `[data-form-field="${name}"]`;
const BAR = '[data-testid="script-consent-bar"]';

/** Wait until the overlay input `selector` shows `want`; the message names what it showed. */
async function waitForValue(j: Journey, selector: string, want: string, timeout = 15_000): Promise<void> {
  const until = Date.now() + timeout;
  for (;;) {
    const got = await j.s.call<string>('value', selector);
    if (got === want) return;
    if (Date.now() > until) throw new Error(`${selector} shows ${JSON.stringify(got)}, expected ${JSON.stringify(want)}`);
    await sleep(150);
  }
}

/** Commit the field being typed in: edits commit on blur. */
async function blur(j: Journey): Promise<void> {
  await j.s.click('[data-testid="page-view"]');
  await sleep(300);
}

journey('J-57', async (j) => {
  const doc = j.fixture('src-tauri/tests/fixtures/form_scripts.pdf', 'order.pdf');
  await j.start({ open: doc });
  await j.waitFor('[data-testid="form-overlay"]');

  await j.step('the bar asks; "Run for this document" gives permission', async () => {
    await j.waitFor(BAR);
    await j.s.click('[data-testid="script-consent-run-once"]');
    await j.waitFor(BAR, { state: 'gone' });
  });

  await j.step('the calculation runs, saves and survives a reopen', async () => {
    await fill(j, field('qty'), '3');
    await fill(j, field('price'), '4');
    await blur(j);
    await waitForValue(j, field('total'), '12');

    await fill(j, field('qty'), '5');
    await blur(j);
    await waitForValue(j, field('total'), '20');

    await waitDirty(j, true);
    await save(j);
    const saved = Object.fromEntries((j.inspect(doc).form_fields ?? []).map((f) => [f.name, f.value]));
    expect(saved.qty).toBe('5');
    expect(saved.total, 'the saved file carries the calculated total').toBe('20');

    // A new run opens the file. The bar asks again and has not been answered,
    // so no script has run: the total on screen is the one in the file.
    await j.stop();
    await j.start({ open: doc });
    await j.waitFor('[data-testid="form-overlay"]');
    await j.waitFor(BAR);
    await waitForValue(j, field('total'), '20');
    expect(await j.s.call<string>('value', field('qty'))).toBe('5');
  });
});
